def choose_move(observation):
    def is_num(v):
        return isinstance(v, (int, float)) and not isinstance(v, bool)

    def as_pos(v):
        if isinstance(v, dict):
            if 'x' in v and 'y' in v and is_num(v.get('x')) and is_num(v.get('y')):
                return [int(v.get('x')), int(v.get('y'))]
            if 'col' in v and 'row' in v and is_num(v.get('col')) and is_num(v.get('row')):
                return [int(v.get('col')), int(v.get('row'))]
        if isinstance(v, (list, tuple)) and len(v) >= 2 and is_num(v[0]) and is_num(v[1]):
            return [int(v[0]), int(v[1])]
        return None

    def extract_positions(val):
        out = []
        if val is None:
            return out
        p = as_pos(val)
        if p is not None:
            out.append(p)
            return out
        if isinstance(val, dict):
            for k in ('items', 'positions', 'pos', 'coords', 'cells', 'targets', 'resources', 'enemies', 'opponents', 'players'):
                if k in val:
                    out.extend(extract_positions(val.get(k)))
            return out
        if isinstance(val, (list, tuple)):
            for e in val:
                p = as_pos(e)
                if p is not None:
                    out.append(p)
                elif isinstance(e, dict):
                    out.extend(extract_positions(e))
        return out

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def sign(x):
        return (x > 0) - (x < 0)

    obs = observation if isinstance(observation, dict) else {}
    self_pos = None
    for k in ('self', 'agent', 'player', 'me', 'unit'):
        v = obs.get(k)
        if isinstance(v, dict):
            for kk in ('position', 'pos', 'location', 'loc', 'xy'):
                self_pos = as_pos(v.get(kk))
                if self_pos is not None:
                    break
        else:
            self_pos = as_pos(v)
        if self_pos is not None:
            break
    if self_pos is None:
        for k in ('position', 'pos', 'player_pos', 'agent_pos', 'location', 'loc', 'xy'):
            self_pos = as_pos(obs.get(k))
            if self_pos is not None:
                break
    if self_pos is None:
        return [0, 0]

    # Collect candidate sets
    resource_keys = ('resources', 'resource_positions', 'resource', 'food', 'foods', 'targets', 'goal', 'goals', 'collectibles')
    enemy_keys = ('enemies', 'enemy_positions', 'opponents', 'opponent_positions', 'hostiles', 'adversaries')
    ally_keys = ('allies', 'teammates', 'friends')

    resources = []
    enemies = []
    allies = []

    for k in resource_keys:
        resources.extend(extract_positions(obs.get(k)))
    for k in enemy_keys:
        enemies.extend(extract_positions(obs.get(k)))
    for k in ally_keys:
        allies.extend(extract_positions(obs.get(k)))

    # Optional grid/board for wall checking
    grid = None
    for k in ('grid', 'board', 'map', 'world', 'cells'):
        v = obs.get(k)
        if isinstance(v, (list, tuple)):
            grid = v
            break

    h = len(grid) if isinstance(grid, (list, tuple)) else None
    w = None
    if h:
        first = grid[0]
        if isinstance(first, (list, tuple)):
            w = len(first)

    def passable(x, y):
        if grid is None or h is None or w is None:
            return True
        if y < 0 or y >= h or x < 0 or x >= w:
            return False
        cell = grid[y][x]
        if cell is None:
            return True
        if isinstance(cell, (int, float)):
            return cell == 0 or cell == 1 or cell > -1
        if isinstance(cell, str):
