    nearest_enemy = None
    best_ed = None
    for e in enemies:
        d = manhattan(self_pos, e)
        if best_ed is None or d < best_ed:
            best_ed = d
            nearest_enemy = e

    nearest_target = None
    best_td = None
    for t in resources:
        d = manhattan(self_pos, t)
        if best_td is None or d < best_td:
            best_td = d
            nearest_target = t

    # If no explicit targets, use explored frontier heuristic from nearby open cells.
    def score_move(dx, dy):
