        if nearest_target is not None:
            s += 30 - manhattan([nx, ny], nearest_target) * 3

        # Avoid enemies if close.
        if nearest_enemy is not None:
            old_d = best_ed
            new_d = manhattan([nx, ny], nearest_enemy)
            if old_d is not None:
                s += (new_d - old_d) * 8
            if new_d <= 1:
